/**
 * Bundled template PNGs embedded as base64 so the installer writes them to
 * MyStyle WITHOUT reading the plugin private dir. On Chauvet the PluginHost
 * can run a plugin under ANOTHER plugin sandbox identity, which makes a raw
 * read of the plugin private dir (plugins slash thisID slash drawable) fail
 * with "not allowed to access other plugin private dir" (field report
 * 2026-09-06, Nomad with several plugins installed). Writing to shared storage
 * (MyStyle) is gated only by FILE:WRITE, which works. Generated from
 * assets/templates.
 */
export const TEMPLATE_DATA = {
  'SuperTemplate_simpleNote.png': '',
  'SuperTemplate_simpleNote_logoLight.png': '',
  'SuperTemplate_simpleNote_noLogo.png': '',
  'SuperTemplate_dotGrid.png': '',
  'SuperTemplate_dotGrid_logoLight.png': '',
  'SuperTemplate_dotGrid_noLogo.png': '',
};
